def count_routes(rows, cols, blocked):
    bad = {(r, c) for r, c in blocked}
    ways = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if (r, c) in bad:
                continue
            if r == 0 and c == 0:
                ways[r][c] = 1
            else:
                up = ways[r - 1][c] if r > 0 else 0
                left = ways[r][c - 1] if c > 0 else 0
                ways[r][c] = up + left
    return ways[rows - 1][cols - 1]
```

